import{$ as e,B as t,et as n,pt as r}from"./chunks/framework.KBYRAceO.js";var i=JSON.parse(`{"title":"백엔드 개발자가 알아보는 웹 접근성","description":"","frontmatter":{"title":"백엔드 개발자가 알아보는 웹 접근성","date":"2025-09-22T23:00+09:00","tags":["Web Accessibility","Frontend"]},"headers":[],"relativePath":"posts/a11y.md","filePath":"posts/a11y.md","lastUpdated":1784435026000}`),a={name:`posts/a11y.md`};function o(t,i,a,o,s,c){return r(),e(`div`,null,[...i[0]||=[n(`<p>최근 기획자 직무를 시작하는 지인의 면접을 도와주다 웹 접근성이라는 것을 알게 되었습니다. 조직에서 <mark>백엔드 개발자로 일하고 있어서</mark> 프론트엔드 영역에서 웹 접근성에 대한 중요한 목표가 있음을 인지하지 못했습니다. 그러면, 웹 접근성에 대해서 알아볼까요?</p><h4 id="accessibility" tabindex="-1">Accessibility <a class="header-anchor" href="#accessibility" aria-label="Permalink to “Accessibility”">​</a></h4><p>웹 접근성 또는 디지털 접근성으로 <mark>장애 유무와 관계없이</mark> 누구나 동등한 방식으로 제품과 상호작용할 수 있도록 서비스를 제공하는 것을 말합니다. 국제적인 표준 권장사항은 웹 콘텐츠 접근성 가이드라인 (WCAG)을 따르는 것으로 대한민국의 경우 <mark>한국웹접근성인증평가원으로부터</mark> <a href="http://www.kwacc.or.kr/Accessibility/Certification" target="_blank" rel="noreferrer">KWCAG 인증</a> 심사를 받을 수 있는 것 같습니다. <a href="https://developer.mozilla.org/en-US/docs/Web/Accessibility/Guides/Understanding_WCAG" target="_blank" rel="noreferrer">웹 콘텐츠 접근성 가이드라인 (WCAG)</a>은 키보드 및 스크린리더 사용자가 모든 요소를 이용할 수 있고 링크 텍스트와 색상 및 대비가 명확해야합니다.</p><p>웹 접근성은 <a href="https://nuli.navercorp.com/" target="_blank" rel="noreferrer">네이버 널리(NULI)</a> 또는 <a href="https://web.dev/learn/accessibility" target="_blank" rel="noreferrer">Learn Accessibility</a>를 통해 배울 수 있고 아래의 방법으로 웹 접근성에 대한 준수 여부를 검사해볼 수 있었습니다.</p><ul><li><a href="https://developer.chrome.com/docs/lighthouse" target="_blank" rel="noreferrer">Chrome DevTools - Lighthouse</a></li><li><a href="https://accessibility.kr/" target="_blank" rel="noreferrer">웹 접근성 진단 서비스</a></li></ul><h4 id="국내-진단-결과" tabindex="-1">국내 진단 결과 <a class="header-anchor" href="#국내-진단-결과" aria-label="Permalink to “국내 진단 결과”">​</a></h4><p>최근 토스 개발자는 <a href="https://frontend-fundamentals.com/a11y/" target="_blank" rel="noreferrer">A11y Fundamentals</a>를 공유한 것을 확인할 수 있었는데요. 하지만, 대한민국의 대표 포털 사이트이면서 <a href="https://accessibility.naver.com/" target="_blank" rel="noreferrer">웹 접근성 지침을 따른다는</a> 네이버 뿐만 아니라 국내 개발자 커뮤니티인 <a href="https://accessibility.kr/evaluate/host/okky.kr" target="_blank" rel="noreferrer">OKKY</a>도 웹 접근성을 준수하지 않는 것으로 확인할 수 있습니다. 정부 사이트들은 <a href="https://www.wa.or.kr/board/view.asp?sn=35560" target="_blank" rel="noreferrer">정보통신접근성 품질인증 표준심사</a>를 받지 않더라도 <a href="https://www.krds.go.kr/" target="_blank" rel="noreferrer">대한민국 정부 디자인 시스템(KRDS)</a>에 따라 웹 접근성을 준수하도록 <mark>웹 에이전시에 의해</mark> 만들어지고 있는 것으로 보여집니다.</p><h4 id="그래서-회사-제품은-준수할까요" tabindex="-1">그래서 회사 제품은 준수할까요? <a class="header-anchor" href="#그래서-회사-제품은-준수할까요" aria-label="Permalink to “그래서 회사 제품은 준수할까요?”">​</a></h4><p>아니요! 조직에서 개발중인 웹 서비스도 검사를 진행해본 결과 동일하게 준수하지 않는 것으로 확인할 수 있었어요. 그래서 웹 접근성 준수에 대한 이슈를 등록하고 빠르게 공유해야겠습니다.</p><p>감사합니다.</p>`,10)]])}var s=t(a,[[`render`,o]]);export{i as __pageData,s as default};